+        /// <summary>
+        /// 统一比较对象字段
+        /// </summary>
+        /// <param name="beforeObj"></param>
+        /// <param name="afterObj"></param>
+        /// <param name="fields"></param>
+        /// <param name="fieldPrefix"></param>
+        /// <returns></returns>
+        private static List<string> CompareObjectFields(
+            JObject beforeObj,
+            JObject afterObj,
+            IDictionary<string, string> fields,
+            string fieldPrefix = "")
+        {
+            var changes = new List<string>();
+
+            foreach (var field in fields)
+            {
+                string beforeValue = GetFormattedFieldValue(beforeObj, field.Key);
+                string afterValue = GetFormattedFieldValue(afterObj, field.Key);
+
+                if (beforeValue == afterValue)
+                {
+                    continue;
+                }
+
+                string fieldDisplayName = string.IsNullOrWhiteSpace(fieldPrefix)
+                    ? field.Value
+                    : $"{fieldPrefix}{field.Value}";
+
+                if (string.IsNullOrEmpty(beforeValue))
+                {
+                    changes.Add($"新增{fieldDisplayName}：{afterValue}");
+                }
+                else if (string.IsNullOrEmpty(afterValue))
+                {
+                    changes.Add($"删除{fieldDisplayName}：{beforeValue}");
+                }
+                else
+                {
+                    changes.Add($"{fieldDisplayName}由'{beforeValue}'改为'{afterValue}'");
+                }
+            }
+
+            return changes;
+        }
