+        /// <summary>
+        /// 读取命名对象
+        /// </summary>
+        /// <param name="root"></param>
+        /// <param name="propertyNames"></param>
+        /// <returns></returns>
+        private static JObject GetNamedObject(JObject root, params string[] propertyNames)
+        {
+            return GetNamedToken(root, propertyNames) as JObject;
+        }
