+        /// <summary>
+        /// 读取命名数组
+        /// </summary>
+        /// <param name="root"></param>
+        /// <param name="propertyNames"></param>
+        /// <returns></returns>
+        private static JArray GetNamedArray(JObject root, params string[] propertyNames)
+        {
+            return GetNamedToken(root, propertyNames) as JArray;
+        }
+
+        /// <summary>
+        /// 读取命名 token，支持大小写和历史字段名兼容
+        /// </summary>
+        /// <param name="root"></param>
+        /// <param name="propertyNames"></param>
+        /// <returns></returns>
+        private static JToken GetNamedToken(JObject root, params string[] propertyNames)
+        {
+            if (root == null || propertyNames == null || propertyNames.Length == 0)
+            {
+                return null;
+            }
+
+            foreach (var property in root.Properties())
+            {
+                if (propertyNames.Any(name => string.Equals(property.Name, name, StringComparison.OrdinalIgnoreCase)))
+                {
+                    return property.Value;
+                }
+            }
+
+            return null;
+        }
+
+        /// <summary>
+        /// 标准化社保公积金记录顺序
+        /// </summary>
+        /// <param name="records"></param>
+        /// <returns></returns>
+        private static List<JObject> NormalizeSocialSecurityRecords(JArray records)
+        {
+            if (records == null)
+            {
+                return new List<JObject>();
+            }
+
+            return records
+                .OfType<JObject>()
+                .OrderBy(record => record["Type"]?.ToString() ?? string.Empty)
+                .ThenBy(record => record["Id"]?.ToString() ?? string.Empty)
+                .ToList();
+        }
+
+        /// <summary>
+        /// 读取并格式化字段值
+        /// </summary>
+        /// <param name="obj"></param>
+        /// <param name="fieldName"></param>
+        /// <returns></returns>
+        private static string GetFormattedFieldValue(JObject obj, string fieldName)
+        {
+            var token = obj?[fieldName];
+            if (token == null || token.Type == JTokenType.Null || token.Type == JTokenType.Undefined)
+            {
+                return string.Empty;
+            }
+
+            if (token.Type == JTokenType.Date)
+            {
+                return token.Value<DateTime>().ToString("yyyy-MM-dd");
+            }
+
+            var rawValue = token.ToString();
+            if (string.IsNullOrWhiteSpace(rawValue))
+            {
+                return string.Empty;
+            }
+
+            if (fieldName == "Type")
+            {
+                if (int.TryParse(rawValue, out var typeValue) &&
+                    Enum.IsDefined(typeof(SocialsecurityTypeEnums), typeValue))
+                {
+                    return EnumUtility.GetDescription((SocialsecurityTypeEnums)typeValue);
+                }
+
+                if (Enum.TryParse(rawValue, true, out SocialsecurityTypeEnums socialType))
+                {
+                    return EnumUtility.GetDescription(socialType);
+                }
+            }
+
+            if (fieldName == "LeaveReason")
+            {
+                if (int.TryParse(rawValue, out var leaveReasonValue) &&
+                    Enum.IsDefined(typeof(LeaveReasonEnums), leaveReasonValue))
+                {
+                    return EnumUtility.GetDescription((LeaveReasonEnums)leaveReasonValue);
+                }
+
+                if (Enum.TryParse(rawValue, true, out LeaveReasonEnums leaveReason))
+                {
+                    return EnumUtility.GetDescription(leaveReason);
+                }
+            }
+
+            if ((fieldName.EndsWith("Time", StringComparison.OrdinalIgnoreCase) ||
+                 fieldName.EndsWith("Date", StringComparison.OrdinalIgnoreCase)) &&
+                DateTime.TryParse(rawValue, out var parsedDateTime))
+            {
+                return parsedDateTime.ToString("yyyy-MM-dd");
+            }
+
+            return rawValue;
+        }
+        
+    }
